    private static DeferredBlock<Block> register(String name, Function<BlockBehaviour.Properties, Block> factory, Supplier<BlockBehaviour.Properties> properties)
    {
        DeferredBlock<Block> block = REGISTER.registerBlock(name, factory, properties);
        ModItems.REGISTER.registerSimpleBlockItem(name, block);
        return block;
    }

    private static DeferredBlock<Block> register(String name, Function<BlockBehaviour.Properties, Block> factory, Supplier<BlockBehaviour.Properties> properties, BiFunction<DeferredBlock<Block>, Item.Properties, BlockItem> item)
    {
        DeferredBlock<Block> block = REGISTER.registerBlock(name, factory, properties);
        ModItems.REGISTER.registerItem(name, props -> item.apply(block, props), () -> new Item.Properties().useBlockDescriptionPrefix());
        return block;
    }

    private static DeferredBlock<Block> registerNoItem(String name, Function<BlockBehaviour.Properties, Block> factory, Supplier<BlockBehaviour.Properties> properties)
    {
        return REGISTER.registerBlock(name, factory, properties);
    }
